/*
 * A382014  Partial sums of A377225.
 * https://oeis.org/A382014
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = Sum_{k=0..n} A377225(k); A377225 generated by a greedy
 *            search (least unused |value| sharing a factor with previous
 *            term, tie -> positive)
 * Range:     u8 n <= 239, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 90 terms through n = 9157 (2026-11-10)
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/factor_u64.h"

static int64_t *A382014_sums = NULL;   /* partial sums */
static int64_t A382014_last = 0;       /* last term of A377225 */
static size_t A382014_cap = 0, A382014_len = 0;

static uint8_t *A382014_used = NULL;   /* bit0 = positive used, bit1 = negative used */
static size_t A382014_used_cap = 0;

static void A382014_ensure_used(size_t v)
{
    if (v < A382014_used_cap)
        return;
    size_t new_cap = A382014_used_cap ? A382014_used_cap : 16;
    while (new_cap <= v)
        new_cap <<= 1;
    uint8_t *tmp = (uint8_t *)realloc(A382014_used, new_cap);
    if (tmp == NULL)
        abort();
    for (size_t i = A382014_used_cap; i < new_cap; ++i)
        tmp[i] = 0;
    A382014_used = tmp;
    A382014_used_cap = new_cap;
}

static void A382014_grow(size_t target)
{
    if (A382014_len > target)
        return;
    if (A382014_cap < target + 1) {
        size_t new_cap = A382014_cap ? A382014_cap : 16;
        while (new_cap < target + 1)
            new_cap <<= 1;
        int64_t *tmp = (int64_t *)realloc(A382014_sums, new_cap * sizeof(int64_t));
        if (tmp == NULL)
            abort();
        A382014_sums = tmp;
        A382014_cap = new_cap;
    }
    for (size_t i = A382014_len; i <= target; ++i) {
        int64_t val;
        if (i == 0) val = 0;
        else if (i == 1) val = 1;
        else if (i == 2) val = -1;
        else if (i == 3) val = 2;
        else {
            int64_t prev = A382014_last;
            uint64_t abs_prev = prev >= 0 ? (uint64_t)prev : (uint64_t)(-prev);
            uint64_t primes[64];
            uint64_t exps[64];
            size_t cnt = 0;
            if (abs_prev > 1)
                factor_u64(abs_prev, primes, exps, &cnt);
            uint64_t best_abs = UINT64_MAX;
            int best_sign = 0;
            for (size_t k = 0; k < cnt; ++k) {
                uint64_t p = primes[k];
                uint64_t m = p;
                for (;;) {
                    A382014_ensure_used((size_t)m);
                    uint8_t mask = A382014_used[m];
                    if (!(mask & 1)) {
                        if (m < best_abs || (m == best_abs && best_sign > 0)) {
                            best_abs = m;
                            best_sign = 1;
                        }
                        break;
                    } else if (!(mask & 2)) {
                        if (m < best_abs || (m == best_abs && best_sign > 0)) {
                            best_abs = m;
                            best_sign = -1;
                        }
                        break;
                    }
                    m += p;
                }
            }
            if (best_abs == UINT64_MAX)
                val = 0;
            else
                val = best_sign * (int64_t)best_abs;
        }
        A382014_last = val;
        if (val != 0 && i > 0) {
            uint64_t av = val > 0 ? (uint64_t)val : (uint64_t)(-val);
            A382014_ensure_used((size_t)av);
            A382014_used[av] |= (val > 0) ? 1 : 2;
        }
        A382014_sums[i] = (i ? A382014_sums[i - 1] : 0) + val;
    }
    A382014_len = target + 1;
}

seq_t a(idx_t n)
{
    A382014_grow((size_t)n);
    return (seq_t)A382014_sums[(size_t)n];
}
